#ifndef __IGEMM_GTC_BASE_H
#define __IGEMM_GTC_BASE_H

#ifdef USE_HALF
#include "half.hpp"
using float16 = half_float::half;
#else
using float16 = int16_t;
#endif
#include <hip/hip_ext.h>
#include <hip/hip_runtime.h>
#include "config_parser.h"
#include "utility.h"
