    int output_size;
} __attribute__((packed)) wrw_reduce_karg_t;

static inline size_t get_data_byte(driverDataType_t dtype)
{
    if(dtype == driverHalf)
        return 2;
    if(dtype == driverFloat)
        return 4;
    if(dtype == driverInt8)
        return 1;
    if(dtype == driverBFloat16)
        return 2;
    if(dtype == driverInt4)
        return 1;
    assert(0);
    return 0;
}

